from rest_framework.permissions import BasePermission


class IsOwner(BasePermission):
    message = "شما مالک این شیء نیستید."

    def has_object_permission(self, request, view, obj):
        return obj.owner == request.user

from rest_framework.permissions import BasePermission, SAFE_METHODS


class IsOwnerOrReadOnly(BasePermission):
    message = "فقط مالک می‌تواند این شیء را ویرایش یا حذف کند."

    def has_object_permission(self, request, view, obj):
        # متدهای خواندنی برای همه مجاز
        if request.method in SAFE_METHODS:
            return True
        # متدهای نوشتنی فقط برای مالک
        return obj.owner == request.user

class IsEditor(BasePermission):
    message = "این عمل فقط برای ویرایشگرها مجاز است."

    def has_permission(self, request, view):
        user = request.user
        return bool(
            user and
            user.is_authenticated and
            user.groups.filter(name="editor").exists()
        )


class IsModerator(BasePermission):
    message = "این عمل فقط برای مدیران محتوا مجاز است."

    def has_permission(self, request, view):
        user = request.user
        return bool(
            user and
            user.is_authenticated and
            user.groups.filter(name="moderator").exists()
        )

class ArticleViewSet(viewsets.ModelViewSet):
    queryset = Article.objects.all()
    serializer_class = ArticleSerializer

    def get_permissions(self):
        if self.action in ("destroy",):
            return [IsModerator()]
        if self.action in ("create", "update", "partial_update"):
            return [IsEditor()]
        return [AllowAny()]

class IsOwnerOrAdmin(BasePermission):
    message = "فقط مالک یا ادمین می‌تواند این عمل را انجام دهد."

    def has_object_permission(self, request, view, obj):
        user = request.user
        if user.is_staff:
            return True
        return obj.owner == user


class IsAuthorOrEditorOrReadOnly(BasePermission):
    message = "فقط نویسنده یا ویرایشگر می‌تواند این را تغییر دهد."

    def has_object_permission(self, request, view, obj):
        if request.method in SAFE_METHODS:
            return True
        user = request.user
        if user.is_staff:
            return True
        if user.groups.filter(name="editor").exists():
            return True
        return obj.author == user

class CanEditUnpublishedOnly(BasePermission):
    message = "کتاب‌های منتشرشده قابل ویرایش نیستند."

    def has_object_permission(self, request, view, obj):
        if request.method in SAFE_METHODS:
            return True
        if obj.is_published:
            return False
        return obj.owner == request.user

class CanBeDeleted(BasePermission):
    message = "این سفارش را نمی‌توان حذف کرد."

    def has_object_permission(self, request, view, obj):
        # فقط سفارش‌های در وضعیت pending قابل حذف‌اند
        return obj.status == "pending"

class IsInSameOrganization(BasePermission):
    message = "شما به این سازمان دسترسی ندارید."

    def has_permission(self, request, view):
        user = request.user
        if not user or not user.is_authenticated:
            return False
        return user.organization_id is not None

    def has_object_permission(self, request, view, obj):
        if request.user.is_staff:
            return True
        return obj.organization_id == request.user.organization_id

class InvoiceViewSet(viewsets.ModelViewSet):
    serializer_class = InvoiceSerializer
    permission_classes = [IsAuthenticated, IsInSameOrganization]

    def get_queryset(self):
        # فقط فاکتورهای سازمان کاربر
        if self.request.user.is_staff:
            return Invoice.objects.all()
        return Invoice.objects.filter(
            organization=self.request.user.organization
        )

