from rest_framework import viewsets
from rest_framework.permissions import IsAuthenticated


class NoteViewSet(viewsets.ModelViewSet):
    serializer_class = NoteSerializer
    permission_classes = [IsAuthenticated, IsNoteOwner]
    lookup_field = "slug"

    def get_queryset(self):
        # فقط یادداشت‌های خود کاربر
        # این خط باعث می‌شود 404 بدهد به‌جای 403 برای یادداشت دیگران
        return (
            Note.objects
            .filter(owner=self.request.user)
            .select_related("owner")
        )

    def perform_create(self, serializer):
        serializer.save(owner=self.request.user)

class IsAdminOrReadOnly(BasePermission):
    message = "فقط ادمین می‌تواند این را تغییر دهد."

    def has_permission(self, request, view):
        if request.method in SAFE_METHODS:
            return True
        return bool(request.user and request.user.is_staff)

from django.utils.translation import gettext_lazy as _
from rest_framework.permissions import BasePermission


class IsOwner(BasePermission):
    message = _("شما مالک این شیء نیستید.")

    def has_object_permission(self, request, view, obj):
        return obj.owner == request.user

# AND — هر دو باید True باشند
permission_classes = [IsAuthenticated, IsOwner]


# OR — یکی کافی است
class IsOwnerOrAdmin(BasePermission):
    def has_object_permission(self, request, view, obj):
        return request.user.is_staff or obj.owner == request.user


# NOT — معکوس کردن
class IsNotBanned(BasePermission):
    def has_permission(self, request, view):
        if not request.user.is_authenticated:
            return True   # کاربر ناشناس ربطی ندارد
        return not request.user.is_banned

# ترکیب پیچیده: ادمین یا (مالک و منتشرنشده)
class CanEditArticle(BasePermission):
    def has_object_permission(self, request, view, obj):
        if request.method in SAFE_METHODS:
            return True
        if request.user.is_staff:
            return True
        return obj.author == request.user and not obj.is_published
